{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "A polar pterin raised BH4 in CSF within 90 minutes after i.v. dosing, directly demonstrating meaningful CNS access despite high polarity; this is the highest-transfer analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "MTX-241F, a brain-penetrant aminopyrimidine inhibitor, achieved micromolar murine brain levels after systemic administration, supporting CNS access for the query's aminopyrimidine/morpholine chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lorlatinib showed CSF/free plasma ratios of 0.61-0.96 in humans and PET-confirmed high brain uptake, providing strong direct human evidence that similar heteroaromatic primary-amine compounds can achieve robust CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ribociclib, a polar aminopyrimidine kinase inhibitor, was detected at clinically relevant CSF levels in patients, supporting meaningful CNS access despite polar and potentially efflux-prone features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "ETC-168, a morpholine amide-containing brain-penetrant inhibitor, had a brain/plasma ratio of 0.12 in mice, which was considered significant brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Compound 6, containing a morpholine sulfonamide and heteroaromatic core, showed a B/P ratio of 2.4 in rats, indicating high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "CZC25146, a morpholine-containing aminopyrimidine, showed negligible brain penetration in mice; this is the main contradictory evidence but is outweighed by the more numerous and higher-transfer direct pass measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer direct CNS-exposure measurements—CSF/plasma ratios, brain tissue levels, PET imaging, and brain/plasma ratios—in structurally related polar heteroaromatic compounds support meaningful CNS access for the query. The single negative analogue is outweighed, and the low passive-diffusion prior is not decisive.",
  "evidence_gaps": [
    "No direct brain or CSF measurement exists for the exact query molecule; prediction relies on transferable analogues.",
    "Efflux transporter phenotype of the query (e.g., P-gp/BCRP) is not directly measured; the physicochemical prior suggests possible efflux liability.",
    "The single negative analogue C20 indicates that some morpholine/aminopyrimidine compounds can have negligible brain penetration, so the margin is not absolute."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

